/** The seconds a retry-after header asks for (delta-seconds or an HTTP date; past dates are 0), null when absent or unreadable. */
function retryAfterS(headers: Headers): number | null {
  const ra = headers.get(HEADERS.retryAfter);
  if (!ra || ra.trim() === "") return null;
  let s = Number(ra);
  if (!Number.isFinite(s)) s = (Date.parse(ra) - Date.now()) / 1000;
  return Number.isFinite(s) ? Math.max(0, s) : null;
}

/**
 * Auto-pagination over a list endpoint: `for await (const item of paginator)`, or `.byPage()` for whole pages.
 * Guards: maxPages and maxCredits. After the loop, `pagesFetched`, `creditsCharged`, `stopReason` and `endReason`
 * say what happened.
 */
export class Paginator<T, M = EnvelopeMeta> implements AsyncIterable<T> {
  /** Pages fetched so far. */
  pagesFetched = 0;
  /** Credits charged so far. */
  creditsCharged = 0;
  /** Why the iteration stopped: "end" (the API's last page) or an SDK guard; null while it runs. */
  stopReason: StopReason | null = null;
  /**
   * The API's page.end_reason when stopReason is "end" (why the list has no more pages: the list ended, the
   * platform's limit, the API's own page cap); null while it runs, after a guard stopped it, or when the API sent none.
   */
  endReason: string | null = null;
  readonly #fetchPage: (cursor: string | undefined) => Promise<ListResult<T, M>>;
  readonly #start: string | undefined;
  readonly #pagePrice: number;
  readonly #options: IterateOptions;

  constructor(
    fetchPage: (cursor: string | undefined) => Promise<ListResult<T, M>>,
    start: string | undefined,
    pagePrice: number,
    options: IterateOptions,
  ) {
    this.#fetchPage = fetchPage;
    this.#start = start;
    this.#pagePrice = pagePrice;
    this.#options = options;
  }

  /** Every page, in order. */
  async *byPage(): AsyncGenerator<ListResult<T, M>, void, undefined> {
    let cursor = this.#start;
    const { maxPages, maxCredits } = this.#options;
    for (;;) {
      if (maxPages !== undefined && this.pagesFetched >= maxPages) {
        this.stopReason = "max_pages";
        return;
      }
      if (maxCredits !== undefined && this.creditsCharged + this.#pagePrice > maxCredits) {
        this.stopReason = "max_credits";
        return;
      }
      const page = await this.#fetchPage(cursor);
      this.pagesFetched++;
      this.creditsCharged += page.credits.charged;
      yield page;
      const next = page.page.next_cursor;
      if (!page.page.has_more || !next) {
        const reason = (page.page as unknown as Record<string, unknown>).end_reason;
        this.stopReason = "end";
        this.endReason = typeof reason === "string" ? reason : null;
        return;
      }
      cursor = next;
    }
  }

  async *[Symbol.asyncIterator](): AsyncGenerator<T, void, undefined> {
    for await (const page of this.byPage()) yield* page.data;
  }

  /** Collect every item (bounded by the guards). */
  async toArray(): Promise<T[]> {
    const out: T[] = [];
    for await (const item of this) out.push(item);
    return out;
  }
}
